export interface UpgradeDef {
  slot: string;         // "click" | "e" | "r" | "f" | "q"
  displayKey: string;   // "Click" | "E" | "R" | "F" | "Q"
  name: string;
  description: string;
  price: number;
  currency?: 'shards' | 'corrupt'; // defaults to 'shards'
}

export interface ElementUpgrades {
  elementId: string;
  upgrades: UpgradeDef[];
}

